teMonitorOutput$modifiedAt' => '<p>The last date and time that the monitor was modified.</p>', 'UpdatePerformanceMonitorOutput$createdAt' => '<p>The date and time when the performance monitor was created.</p>', 'UpdatePerformanceMonitorOutput$modifiedAt' => '<p>The date and time when the performance monitor was last modified.</p>', ], ], 'KubernetesMetadata' => [ 'base' => '<p>Meta data about Kubernetes resources.</p>', 'refs' => [ 'MonitorTopContributorsRow$kubernetesMetadata' => '<p>Meta data about Kubernetes resources.</p>', ], ], 'Limit' => [ 'base' => NULL, 'refs' => [ 'StartQueryMonitorTopContributorsInput$limit' => '<p>The maximum number of top contributors to return.</p>', 'StartQueryWorkloadInsightsTopContributorsInput$limit' => '<p>The maximum number of top contributors to return.</p>', ], ], 'ListMonitorsInput' => [ 'base' => NULL, 'refs' => [], ], 'ListMonitorsOutput' => [ 'base' => NULL, 'refs' => [], ], 'ListPerformanceMonitorsInput' => [ 'base' => NULL, 'refs' => [], ], 'ListPerformanceMonitorsOutput' => [ 'base' => NULL, 'refs' => [], ], 'ListScopesInput' => [ 'base' => NULL, 'refs' => [], ], 'ListScopesOutput' => [ 'base' => NULL, 'refs' => [], ], 'ListTagsForResourceInput' => [ 'base' => NULL, 'refs' => [], ], 'ListTagsForResourceOutput' => [ 'base' => NULL, 'refs' => [], ], 'Long' => [ 'base' => NULL, 'refs' => [ 'MonitorTopContributorsRow$value' => '<p>The value of the metric for a top contributor network flow.</p>', 'Network$asNumber' => '<p>The autonomous system number (ASN) of the autonomous system that the network belongs to.</p>', 'WorkloadInsightsTopContributorsRow$value' => '<p>The value for a metric.</p>', ], ], 'MaxResults' => [ 'base' => NULL, 'refs' => [ 'GetMonitorScopeSuggestionsInput$maxResults' => '<p>The number of query results that you want to return with this call.</p>', 'ListMonitorsInput$maxResults' => '<p>The number of query results that you want to return with this call.</p>', 'ListPerformanceMonitorsInput$maxResults' => '<p>The number of performance monitors that you want to return with this call. If you don\'t specify a value, the default is 25.</p>', 'ListScopesInput$maxResults' => '<p>The number of query results that you want to return with this call.</p>', ], ], 'MetricUnit' => [ 'base' => NULL, 'refs' => [ 'GetQueryResultsMonitorTopContributorsOutput$unit' => '<p>The units for a metric returned by the query.</p>', 'GetQueryResultsWorkloadInsightsTopContributorsDataOutput$unit' => '<p>The units for a metric returned by the query.</p>', ], ], 'MonitorArn' => [ 'base' => NULL, 'refs' => [ 'CreateMonitorOutput$monitorArn' => '<p>The Amazon Resource Name (ARN) of the monitor.</p>', 'CreatePerformanceMonitorOutput$monitorArn' => '<p>The Amazon Resource Name (ARN) of the performance monitor.</p>', 'GetMonitorOutput$monitorArn' => '<p>The Amazon Resource Name (ARN) of the monitor.</p>', 'GetMonitorScopeSuggestionsInput$monitorArn' => '<p>The Amazon Resource Name (ARN) of the monitor that you want to return scope suggestions for.</p>', 'GetPerformanceMonitorOutput$monitorArn' => '<p>The Amazon Resource Name (ARN) of the performance monitor.</p>', 'MonitorSummary$monitorArn' => '<p>The Amazon Resource Name (ARN) of the monitor.</p>', 'PerformanceMonitorSummary$monitorArn' => '<p>The Amazon Resource Name (ARN) of the performance monitor.</p>', 'UpdateMonitorOutput$monitorArn' => '<p>The Amazon Resource Name (ARN) of the monitor.</p>', 'UpdatePerformanceMonitorOutput$monitorArn' => '<p>The Amazon Resource Name (ARN) of the performance monitor.</p>', ], ], 'MonitorList' => [ 'base' => NULL, 'refs' => [ 'ListMonitorsOutput$monitors' => '<p>The monitors that are in an account.</p>', ], ], 'MonitorLocalResource' => [ 'base' => '<p>A local resource is the host where the agent is installed. Local resources can be a a subnet, a VPC, an Availability Zone, an EKS cluster or an Amazon Web Services Region.</p>', 'refs' => [ 'CreateMonitorInputLocalResourcesList$member' => NULL, 'MonitorLocalResources$member' => NULL, ], ], 'MonitorLocalResourceType' => [ 'base' => NULL, 'refs' => [ 'MonitorLocalResource$type' => '<p>The type of the local resource. Valid values are <code>AWS::EC2::VPC</code> <code>AWS::AvailabilityZone</code>, <code>AWS::EC2::Subnet</code>, <code>AWS::EKS::Cluster</code>, or <code>AWS::Region</code>.</p>', ], ], 'MonitorLocalResources' => [ 'base' => NULL, 'refs' => [ 'CreateMonitorOutput$localResources' => '<p>The local resources to monitor. A local resource in a workload is the location of hosts where the Network Flow Monitor agent is installed. </p>', 'GetMonitorOutput$localResources' => '<p>The local resources to monitor. A local resource in a workload is the location of the hosts where the Network Flow Monitor agent is installed. </p>', 'UpdateMonitorInput$localResourcesToAdd' => '<p>Additional local resources to specify network flows for a monitor, as an array of resources with identifiers and types. A local resource in a workload is the location of hosts where the Network Flow Monitor agent is installed. </p>', 'UpdateMonitorInput$localResourcesToRemove' => '<p>The local resources to remove, as an array of resources with identifiers and types.</p>', 'UpdateMonitorOutput$localResources' => '<p>The local resources to monitor. A local resource in a workload is the location of hosts where the Network Flow Monitor agent is installed. </p>', ], ], 'MonitorMetric' => [ 'base' => NULL, 'refs' => [ 'StartQueryMonitorTopContributorsInput$metricName' => '<p>The metric that you want to query top contributors for. That is, you can specify a metric with this call and return the top contributor network flows, for that type of metric, for a monitor and (optionally) within a specific category, such as network flows between Availability Zones.</p>', ], ], 'MonitorRemoteResource' => [ 'base' => '<p>A remote resource is the other endpoint in a network flow. That is, one endpoint is the local resource and the other is the remote resource. The values you can specify are the following:</p> <ul> <li> <p>For a VPC or subnet, this identifier is the VPC Amazon Resource Name (ARN) or subnet ARN.</p> </li> <li> <p>For a service, this identifier is one of the following strings: <code>S3</code> or <code>DynamoDB</code>.</p> </li> <li> <p>For an Availability Zone, this identifier is the AZ name, for example, us-west-2b.</p> </li> <li> <p>For a Region, this identifier is the Region name, for example, us-west-2.</p> </li> </ul> <p>When a remote resource is an Amazon Web Services Region, Network Flow Monitor provides network performance measurements up to the edge of the Region that you specify.</p>', 'refs' => [ 'MonitorRemoteResources$member' => NULL, ], ], 'MonitorRemoteResourceType' => [ 'base' => NULL, 'refs' => [ 'MonitorRemoteResource$type' => '<p>The type of the remote resource. Valid values are <code>AWS::EC2::VPC</code> <code>AWS::AvailabilityZone</code>, <code>AWS::EC2::Subnet</code>, <code>AWS::AWSService</code>, or <code>AWS::Region</code>.</p>', ], ], 'MonitorRemoteResources' => [ 'base' => NULL, 'refs' => [ 'CreateMonitorInput$remoteResources' => '<p>The remote resources to monitor. A remote resource is the other endpoint in the bi-directional flow of a workload, with a local resource. For example, Amazon Dynamo DB can be a remote resource.</p> <p>When you specify remote resources, be aware that specific combinations of resources are allowed and others are not, including the following constraints:</p> <ul> <li> <p>All remote resources that you specify must all belong to a single Region.</p> </li> <li> <p>If you specify Amazon Web Services services as remote resources, any other remote resources that you specify must be in the current Region.</p> </li> <li> <p>When you specify a remote resource for another Region, you can only specify the <code>Region</code> resource type. You cannot specify a subnet, VPC, or Availability Zone in another Region.</p> </li> <li> <p>If you leave the <code>RemoteResources</code> parameter empty, the monitor will include all network flows that terminate in the current Region.</p> </li> </ul>', 'CreateMonitorOutput$remoteResources' => '<p>The remote resources to monitor. A remote resource is the other endpoint specified for the network flow of a workload, with a local resource. For example, Amazon Dynamo DB can be a remote resource. </p>', 'GetMonitorOutput$remoteResources' => '<p>The remote resources to monitor. A remote resource is the other endpoint specified for the network flow of a workload, with a local resource. For example, Amazon Dynamo DB can be a remote resource. </p>', 'UpdateMonitorInput$remoteResourcesToAdd' => '<p>The remote resources to add, as an array of resources with identifiers and types.</p> <p>A remote resource is the other endpoint in the flow of a workload, with a local resource. For example, Amazon Dynamo DB can be a remote resource. </p>', 'UpdateMonitorInput$remoteResourcesToRemove' => '<p>The remote resources to remove, as an array of resources with identifiers and types.</p> <p>A remote resource is the other endpoint specified for the network flow of a workload, with a local resource. For example, Amazon Dynamo DB can be a remote resource. </p>', 'UpdateMonitorOutput$remoteResources' => '<p>The remote resources updated for a monitor, as an array of resources with identifiers and types.</p> <p>A remote resource is the other endpoint specified for the network flow of a workload, with a local resource. For example, Amazon Dynamo DB can be a remote resource.</p>', ], ], 'MonitorStatus' => [ 'base' => NULL, 'refs' => [ 'CreateMonitorOutput$monitorStatus' => '<p>The status of a monitor. The status can be one of the following</p> <ul> <li> <p> <code>PENDING</code>: The monitor is in the process of being created.</p> </li> <li> <p> <code>ACTIVE</code>: The monitor is active.</p> </li> <li> <p> <code>INACTIVE</code>: The monitor is inactive.</p> </li> <li> <p> <code>ERROR</code>: Monitor creation failed due to an error.</p> </li> <li> <p> <code>DELETING</code>: The monitor is in the process of being deleted.</p> </li> </ul>', 'CreatePerformanceMonitorOutput$monitorStatus' => '<p>The status of a performance monitor. The status can be one of the following</p> <ul> <li> <p> <code>PENDING</code>: The performance monitor is in the process of being created.</p> </li> <li> <p> <code>ACTIVE</code>: The performance monitor is active.</p> </li> <li> <p> <code>INACTIVE</code>: The performance monitor is inactive.</p> </li> <li> <p> <code>ERROR</code>: The performance monitor can\'t be created or updated.</p> </li> <li> <p> <code>DELETING</code>: The performance monitor is in the process of being deleted.</p> </li> </ul>', 'GetMonitorOutput$monitorStatus' => '<p>The status of a monitor. The status can be one of the following</p> <ul> <li> <p> <code>PENDING</code>: The monitor is in the process of being created.</p> </li> <li> <p> <code>ACTIVE</code>: The monitor is active.</p> </li> <li> <p> <code>INACTIVE</code>: The monitor is inactive.</p> </li> <li> <p> <code>ERROR</code>: Monitor creation failed due to an error.</p> </li> <li> <p> <code>DELETING</code>: The monitor is in the process of being deleted.</p> </li> </ul>', 'GetPerformanceMonitorOutput$monitorStatus' => '<p>The status of a performance monitor. The status can be one of the following</p> <ul> <li> <p> <code>PENDING</code>: The performance monitor is in the process of being created.</p> </li> <li> <p> <code>ACTIVE</code>: The performance monitor is active.</p> </li> <li> <p> <code>INACTIVE</code>: The performance monitor is inactive.</p> </li> <li> <p> <code>ERROR</code>: The performance monitor can\'t be created or updated.</p> </li> <li> <p> <code>DELETING</code>: The performance monitor is in the process of being deleted.</p> </li> </ul>', 'ListMonitorsInput$monitorStatus' => '<p>The status of a monitor. The status can be one of the following</p> <ul> <li> <p> <code>PENDING</code>: The monitor is in the process of being created.</p> </li> <li> <p> <code>ACTIVE</code>: The monitor is active.</p> </li> <li> <p> <code>INACTIVE</code>: The monitor is inactive.</p> </li> <li> <p> <code>ERROR</code>: Monitor creation failed due to an error.</p> </li> <li> <p> <code>DELETING</code>: The monitor is in the process of being deleted.</p> </li> </ul>', 'ListPerformanceMonitorsInput$monitorStatus' => '<p>The status of the performance monitors that you want to return. If you don\'t specify a status, Network Flow Monitor returns performance monitors with any status.</p>', 'MonitorSummary$monitorStatus' => '<p>The status of a monitor. The status can be one of the following</p> <ul> <li> <p> <code>PENDING</code>: The monitor is in the process of being created.</p> </li> <li> <p> <code>ACTIVE</code>: The monitor is active.</p> </li> <li> <p> <code>INACTIVE</code>: The monitor is inactive.</p> </li> <li> <p> <code>ERROR</code>: Monitor creation failed due to an error.</p> </li> <li> <p> <code>DELETING</code>: The monitor is in the process of being deleted.</p> </li> </ul>', 'PerformanceMonitorSummary$monitorStatus' => '<p>The status of a performance monitor. The status can be one of the following</p> <ul> <li> <p> <code>PENDING</code>: The performance monitor is in the process of being created.</p> </li> <li> <p> <code>ACTIVE</code>: The performance monitor is active.</p> </li> <li> <p> <code>INACTIVE</code>: The performance monitor is inactive.</p> </li> <li> <p> <code>ERROR</code>: The performance monitor can\'t be created or updated.</p> </li> <li> <p> <code>DELETING</code>: The performance monitor is in the process of being deleted.</p> </li> </ul>', 'UpdateMonitorOutput$monitorStatus' => '<p>The status of a monitor. The status can be one of the following</p> <ul> <li> <p> <code>PENDING</code>: The monitor is in the process of being created.</p> </li> <li> <p> <code>ACTIVE</code>: The monitor is active.</p> </li> <li> <p> <code>INACTIVE</code>: The monitor is inactive.</p> </li> <li> <p> <code>ERROR</code>: Monitor creation failed due to an error.</p> </li> <li> <p> <code>DELETING</code>: The monitor is in the process of being deleted.</p> </li> </ul>', 'UpdatePerformanceMonitorOutput$monitorStatus' => '<p>The status of a performance monitor. The status can be one of the following</p> <ul> <li> <p> <code>PENDING</code>: The performance monitor is in the process of being created.</p> </li> <li> <p> <code>ACTIVE</code>: The performance monitor is active.</p> </li> <li> <p> <code>INACTIVE</code>: The performance monitor is inactive.</p> </li> <li> <p> <code>ERROR</code>: The performance monitor can\'t be created or updated.</p> </li> <li> <p> <code>DELETING</code>: The performance monitor is in the process of being deleted.</p> </li> </ul>', ], ], 'MonitorSummary' => [ 'base' => '<p>A summary of information about a monitor, including the ARN, the name, and the status.</p>', 'refs' => [ 'MonitorList$member' => NULL, ], ], 'MonitorTopContributorsRow' => [ 'base' => '<p>A set of information for a top contributor network flow in a monitor. In a monitor, Network Flow Monitor returns information about the network flows for top contributors for each metric. Top contributors are network flows with the top values for each metric type.</p>', 'refs' => [ 'MonitorTopContributorsRowList$member' => NULL, ], ], 'MonitorTopContributorsRowList' => [ 'base' => NULL, 'refs' => [ 'GetQueryResultsMonitorTopContributorsOutput$topContributors' => '<p>The top contributor network flows overall for a specific metric type, for example, the number of retransmissions.</p>', ], ], 'Network' => [ 'base' => '<p>The network that an address in a network flow belongs to.</p>', 'refs' => [ 'AdditionalFlowInfo$network' => '<p>The network that the remote address of the network flow belongs to.</p>', ], ], 'OrgMembershipStatus' => [ 'base' => NULL, 'refs' => [ 'AccountToAdd$membership' => '<p>Whether the account is a member of the same organization as the account that owns the monitor. The membership status can be one of the following</p> <ul> <li> <p> <code>IN_ORG</code>: The account is a member of the same organization.</p> </li> <li> <p> <code>NOT_IN_ORG</code>: The account isn\'t a member of the same organization.</p> </li> <li> <p> <code>UNKNOWN</code>: Network Flow Monitor can\'t determine the organization membership of the account.</p> </li> </ul>', ], ], 'PerformanceMonitorQueryType' => [ 'base' => NULL, 'refs' => [ 'StartQueryPerformanceMonitorInput$queryType' => '<p>The type of query that you want to create. Specify <code>TOP_PATHS</code> to return the top paths for the performance monitor.</p>', ], ], 'PerformanceMonitorSummary' => [ 'base' => '<p>A summary of information about a performance monitor, including the ARN, the name, the status, and the resources that it tracks network performance for.</p>', 'refs' => [ 'PerformanceMonitorSummaryList$member' => NULL, ], ], 'PerformanceMonitorSummaryList' => [ 'base' => NULL, 'refs' => [ 'ListPerformanceMonitorsOutput$monitors' => '<p>The performance monitors in the account.</p>', ], ], 'PerformanceMonitorTarget' => [ 'base' => '<p>A resource that a performance monitor tracks network performance for.</p>', 'refs' => [ 'CreatePerformanceMonitorInputTargetsList$member' => NULL, 'PerformanceMonitorTargets$member' => NULL, 'UpdatePerformanceMonitorInputTargetsToAddList$member' => NULL, 'UpdatePerformanceMonitorInputTargetsToRemoveList$member' => NULL, ], ], 'PerformanceMonitorTargetIdentifierString' => [ 'base' => NULL, 'refs' => [ 'PerformanceMonitorTarget$identifier' => '<p>The Amazon Resource Name (ARN) of the resource that you want Network Flow Monitor to track network performance for.</p>', ], ], 'PerformanceMonitorTargetType' => [ 'base' => NULL, 'refs' => [ 'PerformanceMonitorTarget$type' => '<p>The type of the resource that you want Network Flow Monitor to track network performance for. Specify <code>AWS::EC2::VPC</code>.</p>', ], ], 'PerformanceMonitorTargets' => [ 'base' => NULL, 'refs' => [ 'CreatePerformanceMonitorO